using System;
using System.Collections.Generic;
class LessonDemo {
    static int findRune(int[] values, int target) {
        int low = 0, high = values.Length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (values[mid] == target) return mid;
            if (values[mid] < target) low = mid + 1;
            else high = mid - 1;
        }
        return -1;
    }

    static void Main() {
        int[] runes = { 3, 7, 11, 19, 27, 34 };
        Console.WriteLine(findRune(runes, 19));
    }
}

