using System;
using System.Collections.Generic;
class LessonDemo {
    sealed class Rune {
        public int Power { get; }
        public Rune(int power) { Power = power; }
        public override bool Equals(object obj) {
            return obj is Rune other && Power == other.Power;
        }
        public override int GetHashCode() { return Power.GetHashCode(); }
    }

    static void Main() {
        Rune a = new Rune(8);
        Rune b = new Rune(8);
        Console.WriteLine(a.Equals(b));
    }
}

